import { posix } from "node:path";
import fsPromises from "node:fs/promises";
import fs from "node:fs";
export class FsError extends Error {
    constructor(cause) {
        super(cause.message);
        this.cause = cause;
    }
    get code() {
        if (this.cause.code === "ENOENT")
            return "not-found";
        return "other";
    }
}
/** Synchronously returns a FileInfo for a specific path */
export function statSync(path) {
    try {
        const info = fs.statSync(path);
        return {
            get isFile() {
                return info.isFile();
            },
            get isDirectory() {
                return info.isDirectory();
            },
            get isSymlink() {
                return info.isSymbolicLink();
            },
            size: info.size,
            mtime: info.mtime,
            atime: info.atime,
            ctime: info.ctime,
            birthtime: info.birthtime,
        };
    }
    catch (error) {
        throw new FsError(error);
    }
}
/** Synchronously creates a new directory with the specified path. */
export function mkdirSync(path, recursive) {
    try {
        return fs.mkdirSync(path, { recursive });
    }
    catch (error) {
        throw new FsError(error);
    }
}
/** Synchronously returns an iterable of a directory content */
export async function* readDir(path) {
    const pathLength = path.length;
    try {
        const entries = fsPromises.readdir(path, {
            withFileTypes: true,
            recursive: true,
        });
        for (const entry of await entries) {
            if (!entry.isFile()) {
                continue;
            }
            yield posix.join(entry.parentPath.slice(pathLength), entry.name);
        }
    }
    catch (error) {
        throw new FsError(error);
    }
}
/** Remove a file or folder */
export async function remove(file, recursive) {
    await fsPromises.rm(file, { recursive });
}
/** Rename a file */
export async function rename(from, to) {
    await fsPromises.rename(from, to);
}
/** Read a binary file */
export async function readFile(file) {
    const buf = await fsPromises.readFile(file);
    return new Uint8Array(buf.buffer, buf.byteOffset, buf.length / Uint8Array.BYTES_PER_ELEMENT);
}
/** Read a text file */
export async function readTextFile(file) {
    try {
        return await fsPromises.readFile(file, "utf-8");
    }
    catch (error) {
        throw new FsError(error);
    }
}
/** Write a binary file */
export async function writeFile(file, content) {
    try {
        await fsPromises.writeFile(file, content);
    }
    catch (error) {
        throw new FsError(error);
    }
}
/** Write a text file */
export async function writeTextFile(file, content) {
    try {
        await fsPromises.writeFile(file, content);
    }
    catch (error) {
        throw new FsError(error);
    }
}
